mapper.select:
select teacher.id as teacherId, teacher.name as teacherName, course.id as courseId, course.title as courseTitle, course.lesson_num as courseLessonNum, course.status as courseStatus, course.view_count as courseViewCount, course.buy_count as courseBuyCount, course.apply_count as courseApplyCount, course.cover as courseCover, course.price as coursePrice, course.create_time as courseCreateTime, course.update_time as courseUpdateTime, (select count(*) from edu_chapter e where e.course_id = course.id and e.is_deleted = 0) as chapterQty, (select count(*) from edu_video v1 ,edu_chapter v2 where v2.id = v1.chapter_id and course.id= v2.course_id and v1.is_deleted = 0 and v2.is_deleted = v1.is_deleted ) as videoQty, subject.id as subjectId, subject.title as subjectTitle, subject.sort as subjectSort, subject.create_time as subjectCreateTime, subject.update_time as subjectUpdateTime from edu_course course left join edu_teacher teacher on course.teacher_id = teacher.id left join edu_subject subject on course.subject_id = subject.id where course.is_deleted = 0
and ${ew.sqlSegment}
order by course.title, course.teacher_id, course.create_time
